using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace BWVR {
public sealed class TreePlayWorld:MonoBehaviour {
 public readonly List<ThrowableTree> Trees=new List<ThrowableTree>();public ThrowableTree Active{get;private set;}public Rigidbody Body{get;private set;}public bool Harmful{get;private set;}
 public IslandNavigation Navigation{get;private set;}public float Unit=>Navigation.Scale;public TreePlayMemory Memory=>creature.Season.WorldPlay.Trees;
 CreatureHybrid creature;VillagerSocial[] villagers;PlayImpactTarget[] targets;readonly HashSet<ThrowableTree> candidates=new HashSet<ThrowableTree>();readonly HashSet<string> struck=new HashSet<string>();readonly HashSet<VillagerSocial> witnesses=new HashSet<VillagerSocial>();readonly List<BallCollisionProxy> pool=new List<BallCollisionProxy>();
 Scene scene;PhysicsScene physics;Mesh ground;MeshCollider sculptGroundCollider;CapsuleCollider capsule;float elapsed,refresh,nextInterest;bool completing;
 public static TreePlayWorld Build(Transform parent,IslandNavigation nav,CreatureHybrid god){var go=new GameObject("Creature tree play");go.transform.SetParent(parent,false);var world=go.AddComponent<TreePlayWorld>();world.Initialize(nav,god);return world;}
 void Initialize(IslandNavigation nav,CreatureHybrid god){Navigation=nav;creature=god;villagers=nav.GetComponentsInChildren<VillagerSocial>();targets=nav.GetComponentsInChildren<PlayImpactTarget>();
  var shrubs=new HashSet<int>(nav.Terrain!=null?nav.Terrain.placements.Where(p=>p.kind=="tree"&&p.variant>=13&&p.variant<=15).Select(p=>p.line):Enumerable.Empty<int>());
  Physics.SyncTransforms();foreach(var view in nav.GetComponentsInChildren<IslandPlacementView>()){
   if(view.kind!="tree"||shrubs.Contains(view.sourceLine))continue;var damage=view.GetComponent<PlayImpactTarget>();if(damage==null)continue;
   if(Memory.Find(view.sourceLine)!=null)damage.Apply(0);else if(creature.Season.WorldPlay.Damage(damage.id)>=1)continue;
   var renderers=view.GetComponentsInChildren<Renderer>();if(renderers.Length==0)continue;var bounds=VisualBounds(view.gameObject);float height=bounds.size.y/Unit;if(height<2||height>30)continue;
   var tree=view.gameObject.AddComponent<ThrowableTree>();tree.Initialize(this,view.sourceLine,height);Trees.Add(tree);
   var cue=tree.GetComponent<SpatialTarget>()??tree.gameObject.AddComponent<SpatialTarget>();cue.invoke=()=>{Register(tree);creature.Guide(GuidanceIntent.Investigate,tree.GetComponent<HybridTarget>());};
  }
  scene=SceneManager.CreateScene("BWVR tree flight "+Guid.NewGuid().ToString("N"),new CreateSceneParameters(LocalPhysicsMode.Physics3D));physics=scene.GetPhysicsScene();
  var body=new GameObject("Pooled thrown tree");SceneManager.MoveGameObjectToScene(body,scene);capsule=body.AddComponent<CapsuleCollider>();capsule.contactOffset=.02f;Body=body.AddComponent<Rigidbody>();Body.mass=18;Body.isKinematic=true;Body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;Body.linearDamping=.2f;Body.angularDamping=.5f;body.AddComponent<TreeFlightCollision>().world=this;capsule.enabled=false;
  var floor=new GameObject("Tree flight terrain");SceneManager.MoveGameObjectToScene(floor,scene);if(nav.Terrain!=null){ground=new Mesh{name="Tree flight ground",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};ground.vertices=nav.Terrain.mesh.vertices.Select(nav.ToNav).ToArray();ground.triangles=nav.Terrain.mesh.triangles;ground.RecalculateBounds();sculptGroundCollider=floor.AddComponent<MeshCollider>();sculptGroundCollider.sharedMesh=ground;}else{floor.transform.position=Vector3.down*.5f;floor.AddComponent<BoxCollider>().size=new Vector3(200,1,200);}
  for(int i=0;i<64;i++){var contact=new GameObject("Tree impact pool "+i);SceneManager.MoveGameObjectToScene(contact,scene);contact.AddComponent<BoxCollider>().contactOffset=.02f;contact.AddComponent<Rigidbody>().isKinematic=true;pool.Add(contact.AddComponent<BallCollisionProxy>());contact.SetActive(false);}ResetWorld();
  Debug.Log("BWVR_TREES_READY: "+Trees.Count+" trees, eight nearby candidates, one pooled flight body, 64 contacts, 32 saved moved trees");
 }
 public static Bounds VisualBounds(GameObject tree){var result=new Bounds();bool first=true;foreach(var filter in tree.GetComponentsInChildren<MeshFilter>()){if(filter.sharedMesh==null)continue;var b=filter.sharedMesh.bounds;var m=filter.transform.localToWorldMatrix;var x=m.MultiplyVector(Vector3.right*b.extents.x);var y=m.MultiplyVector(Vector3.up*b.extents.y);var z=m.MultiplyVector(Vector3.forward*b.extents.z);var size=new Vector3(Mathf.Abs(x.x)+Mathf.Abs(y.x)+Mathf.Abs(z.x),Mathf.Abs(x.y)+Mathf.Abs(y.y)+Mathf.Abs(z.y),Mathf.Abs(x.z)+Mathf.Abs(y.z)+Mathf.Abs(z.z))*2;var box=new Bounds(m.MultiplyPoint(b.center),size);if(first){result=box;first=false;}else result.Encapsulate(box);}return result;}
 void Register(ThrowableTree tree){if(tree.GetComponent<HybridTarget>()==null)creature.RegisterObject(tree.Affordance,tree.StableId);}
 public bool Available(ThrowableTree tree)=>!tree.Harvested&&!tree.ResourceReserved&&Active==null&&(tree.Uprooted||Memory.moved.Length<32)&&(tree.Uprooted||creature.Season.WorldPlay.Damage(tree.GetComponent<PlayImpactTarget>().id)<1)&&(candidates.Contains(tree)||(creature.State.guidance.status==GuidanceStatus.Active&&creature.State.guidance.target==tree.StableId));
 public void RefreshInterest(){candidates.Clear();foreach(var tree in Trees.Where(t=>t!=null&&!t.Item.held&&Vector3.Distance(t.transform.position,creature.transform.position)<Unit*120).OrderBy(t=>(t.transform.position-creature.transform.position).sqrMagnitude).Take(8)){Register(tree);candidates.Add(tree);}}
 public void Uprooted(ThrowableTree tree){creature.Journal.Add(creature.State.time,"tree uprooted",CreatureAction.PlayWithToy,tree.StableId,"Trunk removed; physical tree now carried");foreach(var villager in villagers)if(Vector3.Distance(villager.transform.position,tree.transform.position)<Unit*55)villager.ReactToBall(tree.transform,true);}
 public Vector3 Direction(Transform actor){var ball=Navigation.GetComponentInChildren<BeachBall>();return ball!=null?ball.Direction(actor):actor.forward;}
 public bool Throw(ThrowableTree tree,Vector3 direction){if(Active!=null||tree==null||!tree.Uprooted)return false;tree.Item.held=false;tree.Collisions(false);tree.SetObstacle(false);Active=tree;Harmful=false;elapsed=refresh=0;struck.Clear();witnesses.Clear();direction.y=0;if(direction.sqrMagnitude<.01f)direction=Vector3.forward;
  capsule.height=tree.Height;capsule.radius=tree.Radius;capsule.center=Vector3.up*tree.Height*.5f;capsule.enabled=true;Body.position=Navigation.ToNav(tree.transform.position);Body.rotation=tree.transform.rotation;Body.isKinematic=false;Body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;Body.linearVelocity=direction.normalized*16+Vector3.up*6;Body.angularVelocity=Vector3.Cross(Vector3.up,direction.normalized)*4;Body.WakeUp();Memory.throws=Math.Min(1000000,Memory.throws+1);return true;
 }
 void RefreshContacts(){var near=targets.Where(t=>t!=null&&t.gameObject!=Active.gameObject&&t.GetComponent<CarryItem>()?.held!=true&&(t.Bounds(Unit).center-Active.transform.position).sqrMagnitude<Unit*Unit*10000).OrderBy(t=>(t.Bounds(Unit).center-Active.transform.position).sqrMagnitude).Take(pool.Count).ToArray();for(int i=0;i<pool.Count;i++){var p=pool[i];p.target=i<near.Length?near[i]:null;p.gameObject.SetActive(p.target!=null);if(p.target==null)continue;var b=p.target.Bounds(Unit);p.GetComponent<BoxCollider>().size=b.size/Unit;p.GetComponent<Rigidbody>().position=Navigation.ToNav(b.center);}}
 public void Advance(float dt,bool paused){if(paused||dt<=0)return;if(creature.State.time>=nextInterest){nextInterest=creature.State.time+1;RefreshInterest();}if(Active==null)return;dt=Mathf.Min(dt,.1f);refresh-=dt;if(refresh<=0){refresh=.25f;RefreshContacts();}foreach(var proxy in pool)if(proxy.target?.villager!=null)proxy.GetComponent<Rigidbody>().position=Navigation.ToNav(proxy.target.Bounds(Unit).center);
  for(float left=dt;left>0;left-=.02f)physics.Simulate(Mathf.Min(.02f,left));elapsed+=dt;Active.transform.SetPositionAndRotation(Navigation.ToWorld(Body.position),Body.rotation);
  if(Active.transform.position.y<(Navigation.Terrain?.SeaLevel??.82f)-Unit*15||(Active.transform.position-Active.RestPosition).sqrMagnitude>Unit*Unit*90000||elapsed>=12){Active.CancelCarry();Finish();}
  else if(elapsed>.6f&&Body.IsSleeping()){Active.Landed();Finish();}
 }
 public void Impact(PlayImpactTarget target,float speed){if(Active==null||target==null||speed<5||!struck.Add(target.id))return;Harmful=true;float damage=creature.Season.WorldPlay.Hurt(target.id,Mathf.Clamp((speed-3)*.09f,.15f,.8f));target.Apply(damage);if(target.villager!=null)target.villager.Memory.injury=Mathf.Clamp01(target.villager.Memory.injury+.4f);
  foreach(var villager in villagers)if(Vector3.Distance(villager.transform.position,target.transform.position)<Unit*55&&witnesses.Add(villager))villager.ReactToBall(Active.transform,true);
  creature.GetComponent<CreatureCuriosity>().NoticeBadPlay(target.transform);creature.Journal.Add(creature.State.time,"tree impact",CreatureAction.PlayWithToy,Active.StableId,target.id+" damage "+damage.ToString("F2"));
 }
 void Finish(){if(Active==null||completing)return;completing=true;var tree=Active;tree.Collisions(true);Body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;Body.isKinematic=true;capsule.enabled=false;foreach(var proxy in pool)proxy.gameObject.SetActive(false);if(Harmful){Memory.harmfulThrows=Math.Min(Memory.throws,Memory.harmfulThrows+1);Memory.caution=Mathf.Clamp01(Memory.caution+.15f);creature.State.Experience(tree.StableId,-.1f);}else{Memory.safeThrows=Math.Min(Memory.throws,Memory.safeThrows+1);Memory.enjoyment=Mathf.Clamp01(Memory.enjoyment+.04f);creature.State.Experience(tree.StableId,.025f);}creature.Journal.Add(creature.State.time,"tree throw finished",CreatureAction.PlayWithToy,tree.StableId,Harmful?"Damage witnessed":"Physical outcome confirmed");Active=null;completing=false;}
 public void ResetWorld(){if(Active!=null){Active.Item.held=false;Active=null;}if(Body!=null){Body.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;Body.isKinematic=true;capsule.enabled=false;}foreach(var proxy in pool)proxy.gameObject.SetActive(false);foreach(var tree in Trees){tree.Restore(Memory.Find(tree.Line));tree.GetComponent<PlayImpactTarget>().Apply(creature.Season.WorldPlay.Damage(tree.GetComponent<PlayImpactTarget>().id));}nextInterest=0;RefreshInterest();}
 public void RefreshSculptedGround(){if(ground==null||sculptGroundCollider==null)return;ground.vertices=Navigation.Terrain.mesh.vertices.Select(Navigation.ToNav).ToArray();ground.RecalculateBounds();sculptGroundCollider.sharedMesh=null;sculptGroundCollider.sharedMesh=ground;}
 void OnDestroy(){if(ground!=null)Destroy(ground);if(scene.IsValid()&&scene.isLoaded)SceneManager.UnloadSceneAsync(scene);}
}
public sealed class TreeFlightCollision:MonoBehaviour {public TreePlayWorld world;void OnCollisionEnter(Collision collision){world?.Impact(collision.collider.GetComponent<BallCollisionProxy>()?.target,collision.relativeVelocity.magnitude);}}
}
